import { describe, test, expect } from 'vitest';
import { overdueInvoices } from '../src/reports.js';

describe('overdueInvoices', () => {
  test('returns empty array when no invoices provided', () => {
    const result = overdueInvoices([], '2026-10-15');
    expect(result).toEqual([]);
  });

  test('filters out draft invoices', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'draft',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toEqual([]);
  });

  test('filters out paid invoices', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'paid',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toEqual([]);
  });

  test('includes issued invoices', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toHaveLength(1);
    expect(result[0].number).toBe('INV-001');
  });

  test('includes partially_paid invoices', () => {
    const invoices = [
      {
        number: 'INV-002',
        customerId: 'CUST-B',
        status: 'partially_paid',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
        payments: [{ amount: 300, date: '2026-10-05' }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toHaveLength(1);
    expect(result[0].number).toBe('INV-002');
  });

  test('filters out invoices not yet due', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-20',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toEqual([]);
  });

  test('includes invoices due exactly on asOf date', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-15',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toEqual([]);
  });

  test('includes invoices due one day before asOf', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-14',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toHaveLength(1);
    expect(result[0].daysOverdue).toBe(1);
  });

  test('calculates daysOverdue correctly', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result[0].daysOverdue).toBe(14);
  });

  test('calculates due amount for fully unpaid issued invoice', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result[0].due).toBe(1000);
  });

  test('calculates due amount for partially paid invoice', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'partially_paid',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
        payments: [{ amount: 400, date: '2026-10-05' }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result[0].due).toBe(600);
  });

  test('sorts by daysOverdue in descending order', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-10',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
      {
        number: 'INV-002',
        customerId: 'CUST-B',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
      {
        number: 'INV-003',
        customerId: 'CUST-C',
        status: 'issued',
        dueDate: '2026-10-05',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toHaveLength(3);
    expect(result[0].number).toBe('INV-002');
    expect(result[1].number).toBe('INV-003');
    expect(result[2].number).toBe('INV-001');
    expect(result[0].daysOverdue).toBe(14);
    expect(result[1].daysOverdue).toBe(10);
    expect(result[2].daysOverdue).toBe(5);
  });

  test('includes invoice data in output', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result[0]).toHaveProperty('number', 'INV-001');
    expect(result[0]).toHaveProperty('customerId', 'CUST-A');
    expect(result[0]).toHaveProperty('dueDate', '2026-10-01');
    expect(result[0]).toHaveProperty('daysOverdue');
    expect(result[0]).toHaveProperty('due');
  });

  test('handles multiple invoices with different statuses and dates', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
      {
        number: 'INV-002',
        customerId: 'CUST-B',
        status: 'draft',
        dueDate: '2026-09-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
      {
        number: 'INV-003',
        customerId: 'CUST-C',
        status: 'partially_paid',
        dueDate: '2026-10-05',
        lines: [{ qty: 1, unitPrice: 2000, discountPercent: 0, vatRate: 0 }],
        payments: [{ amount: 500, date: '2026-10-06' }],
      },
      {
        number: 'INV-004',
        customerId: 'CUST-D',
        status: 'paid',
        dueDate: '2026-09-15',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
      {
        number: 'INV-005',
        customerId: 'CUST-E',
        status: 'issued',
        dueDate: '2026-10-20',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toHaveLength(2);
    expect(result[0].number).toBe('INV-001');
    expect(result[1].number).toBe('INV-003');
  });

  test('handles invoices with vat and discounts', () => {
    const invoices = [
      {
        number: 'INV-001',
        customerId: 'CUST-A',
        status: 'issued',
        dueDate: '2026-10-01',
        lines: [{ qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 20 }],
      },
    ];
    const result = overdueInvoices(invoices, '2026-10-15');
    expect(result).toHaveLength(1);
    // 1000 - 100 (10% discount) + 180 (20% VAT on 900) = 1080
    expect(result[0].due).toBe(1080);
  });
});

